
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_19_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_19", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.209111227240721e+00, -5.110029889152483e+00, -4.970989499463154e+00, -4.777894713810303e+00, -4.513541228950491e+00, -4.158384641375347e+00, -3.691772829234347e+00, -3.090911227082247e+00, -2.327243653183560e+00, -1.444699985650825e+00, -7.869669349492060e-01, -5.981683088134793e-01, -6.362402051515438e-01, -5.508098083732454e-01, -3.606347304055253e-01, -1.760046651398814e-01, -6.952608290279232e-02, -2.227768973511609e-02, -4.755959735335795e-03, -5.346450591530395e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


